#!/usr/bin/env node
// Generates migrations/0002_seed_rates.sql from packages/engine/src/data/rates.seed.json.
// Do not hand-edit the generated file; edit the JSON and re-run `npm run rates:gen-seed`.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const seedPath = path.join(root, "packages/engine/src/data/rates.seed.json");
const outPath = path.join(root, "migrations/0002_seed_rates.sql");

export function generateSeedSql(snapshot) {
  const q = (v) => (v === null || v === undefined ? "NULL" : `'${String(v).replace(/'/g, "''")}'`);
  const n = (v) => (v === null || v === undefined ? "NULL" : Number(v).toString());
  const lines = [
    "-- GENERATED by scripts/gen-seed-migration.mjs from packages/engine/src/data/rates.seed.json. Do not edit.",
    `INSERT INTO rate_versions (version, status, created_at, published_at, published_by, note) VALUES (${n(snapshot.version)}, 'published', ${q(snapshot.publishedAt)}, ${q(snapshot.publishedAt)}, 'seed', 'Launch values from the PRD');`,
  ];
  for (const key of Object.keys(snapshot.rows).sort()) {
    const r = snapshot.rows[key];
    lines.push(
      "INSERT INTO rates (version, key, value, value_json, unit, range_low, range_high, label_en, label_bn, source_name, source_url, as_of, reviewed_by, next_review, note, is_app_assumption) VALUES (" +
        [
          n(snapshot.version), q(r.key), n(r.value), r.valueJson === undefined ? "NULL" : q(JSON.stringify(r.valueJson)), q(r.unit),
          n(r.rangeLow), n(r.rangeHigh), q(r.labelEn), q(r.labelBn), q(r.sourceName), q(r.sourceUrl), q(r.asOf), q(r.reviewedBy), q(r.nextReview), q(r.note), r.isAppAssumption ? "1" : "0",
        ].join(", ") +
        ");",
    );
  }
  return lines.join("\n") + "\n";
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const snapshot = JSON.parse(fs.readFileSync(seedPath, "utf8"));
  fs.writeFileSync(outPath, generateSeedSql(snapshot));
  console.log(`wrote ${path.relative(root, outPath)} (${Object.keys(snapshot.rows).length} rows)`);
}
